import React, { useEffect, useState } from "react";

import useApi from "../../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../../api/departmentsApi";
import { Loading } from "../../../../components";
import EntityRadiologyServicesFormModal from "./EntityRadiologyServicesFormModal";
import EntityRadiologyServicesTable from "./EntityRadiologyServicesTable";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import { useStateContext } from "../../../../contexts/ContextProvider";

const columns = [
  { name: "Title", uid: "radiology_service_title" },
  { name: "Charge", uid: "charge" },

  { name: "Actions", uid: "actions" },
];

function EntityRadiologyServicesList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedRadiologyService, setselectedRadiologyService] = useState();
  const [entityPhysiotherapyServices, setentityPhysiotherapyServices] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);
  const {loggedInUser}= useStateContext()

  const entityPhysiotherapyServicesApi = useApi(hospitalsApi.hospitalStaffAction);





  const getEntityPhysiotherapyServices = async (data) => {

    await entityPhysiotherapyServicesApi.request({
      "action":"GetEntityRadiologyServices"

  });
  };

  useEffect(() => {
    if (entityPhysiotherapyServicesApi.data) {
      if (entityPhysiotherapyServicesApi.data.length) {
        setentityPhysiotherapyServices(entityPhysiotherapyServicesApi.data);
      }
    }
  }, [entityPhysiotherapyServicesApi.data]);

  useEffect(() => {

    getEntityPhysiotherapyServices();


  }, []);

  useEffect(() => {
    setdata(entityPhysiotherapyServices);
  }, [entityPhysiotherapyServices]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedRadiologyService(item);
    setmodalTitle(`EDIT ${item.radiology_service_title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new radiology service");
    setselectedRadiologyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (entityPhysiotherapyServicesApi.data && entityPhysiotherapyServicesApi.data.length) {
      setentityPhysiotherapyServices(entityPhysiotherapyServicesApi.data);
    }
    console.log("entityLaboratoryServicesApi.data", entityPhysiotherapyServicesApi.data);
  }, [entityPhysiotherapyServicesApi.data]);

  useEffect(() => {
    if (updated === true) {

      getEntityPhysiotherapyServices();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(entityPhysiotherapyServices);
  }, [entityPhysiotherapyServices]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      entityPhysiotherapyServices &&
      entityPhysiotherapyServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        entityPhysiotherapyServices.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(entityPhysiotherapyServices);
    }
  };

  return entityPhysiotherapyServicesApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
        {openInventoryFormModal && (
          <EntityRadiologyServicesFormModal
            ismodalOpen={openInventoryFormModal}
            setisModalOpen={setopenInventoryFormModal}
            selectedRadiologyService={selectedRadiologyService}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}

        <EntityRadiologyServicesTable
      title={"Radiology Services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default EntityRadiologyServicesList;
