import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {

  Button,

} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomTextArea,
  Loading,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import "dayjs/locale/en-gb";
import { Modal } from "antd";
import { useStateContext } from "../../../../contexts/ContextProvider";
import servicesApi from "../../../../api/servicesApi";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";
import departmentsApi from "../../../../api/departmentsApi";

export default function EntityRadiologyServicesFormModal({
  ismodalOpen,
  setisModalOpen,
   selectedRadiologyService,
  modalTitle = "Add radiology service",
  updated,
  setUpdated,
}) {
  const moment = require("moment");
  const { currentColor, loggedInUser } = useStateContext()


  const [errors, setErrors] = useState();


  useEffect(() => {
    if (loggedInUser) {
      getDepartments();
    }
  }, [loggedInUser]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);


  const entityRadiologyServicesApi = useApi(hospitalsApi.hospitalStaffAction)
  const handleRadiologyServiceAction = async (data) => {

    await entityRadiologyServicesApi.request(data)
  }


  useEffect(() => {
    if (entityRadiologyServicesApi.data) {
      if (entityRadiologyServicesApi.data.entity_radiology_service) {
        toast.success(entityRadiologyServicesApi.data.response_message)
        setUpdated(true)
        setisModalOpen(false)
      }


      if (entityRadiologyServicesApi.data.errors) {
        setErrors(entityRadiologyServicesApi.data.errors)
      }
    }
  }, [entityRadiologyServicesApi.data])

  const formik = useFormik({
    initialValues: {

      charge: selectedRadiologyService ? selectedRadiologyService.charge : "",
      title: selectedRadiologyService ? selectedRadiologyService.title : "",
      department: selectedRadiologyService ? {label:selectedRadiologyService.department_title, value: selectedRadiologyService.department} : "",
      radiology_service: selectedRadiologyService ? {label:selectedRadiologyService.radiology_service_title, value: selectedRadiologyService.radiology_service} : "",

    },

    validationSchema: Yup.object({
      charge: Yup.string().required().label("Title"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let data = null;

      if (selectedRadiologyService) {
        data = {
          "action": "UpdateEntityRadiologyService",
          "entity_radiology_service": selectedRadiologyService.id,
          "charge": values.charge,


        }
      } else {
        data = {
          "action": "CreateEntityRadiologyService",
          "radiology_service": values.radiology_service.value,
          "department": values.department.value,
          "charge": values.charge
        }
        console.log("data",data)

      }
      handleRadiologyServiceAction(data)
      // resetForm();
    },
  });




  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  //Search radiology services

  const searchRadiologyServicesApi = useApi(hospitalsApi.hospitalStaffAction);

  const searchLaboratoryServices = async (data) => {
    await searchRadiologyServicesApi.request(data);
  };
  const [radiologyServices, setradiologyServices] = useState();
  const loadRadiologyServicesOptions = async (inputText = "", callback) => {
    searchLaboratoryServices({
      action: "SearchRadiologyServices",
      searchQuery: inputText,
    });
    callback(radiologyServices.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchRadiologyServicesApi.data) {
      
      if (searchRadiologyServicesApi.data.length) {
        setradiologyServices(searchRadiologyServicesApi.data);
      } else {
        setradiologyServices([])
      }
    }
    console.log("searchProductsApi.data", searchRadiologyServicesApi.data);
  }, [searchRadiologyServicesApi.data]);

  //Retrieve departments
  const [departments, setDepartments] = useState([]);
  const departmentsActionsApi = useApi(departmentsApi.departmentsAction);
  const getDepartments = async () => {
    await departmentsActionsApi.request({
      action: "GetEntityDepartments",
      entity: loggedInUser.entity_id,
    });
  };

  useEffect(() => {
    if (departmentsActionsApi.data && departmentsActionsApi.data.length) {
      setDepartments(
        departmentsActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("departmentsActionsApi.data", departmentsActionsApi.data);
  }, [departmentsActionsApi.data]);




  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedRadiologyService ? `EDIT ${selectedRadiologyService.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">

            <CustomFormItem
              touched={formik.touched.radiology_service}
              error={formik.errors.radiology_service}
            >
              <CustomSelectAsyncSelect
                className="text-start"
                name="radiology_service"
                id="radiology_service"
                label="Select radiology service"
                size="large"
                onChange={(value) => formik.setFieldValue("radiology_service", value)}
                value={formik.values.radiology_service}
                placeholder="Select radiology service"
                loadOptions={loadRadiologyServicesOptions}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.department}
              error={formik.errors.department}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="department"
                id="department"
                label="Select department"
                size="large"
                onChange={(value) => formik.setFieldValue("department", value)}
                value={formik.values.department}
                placeholder="Select department"
                options={departments}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.charge}
              error={formik.errors.charge}
            >
              <CustomInput
                className="uppercase"
                required={true}
                label="Enter charge"
                id="charge"
                name="charge"
                onChange={formik.handleChange}
                placeholder="Enter charge"
                size="large"
                type="text"
                value={formik.values.charge}
              />
            </CustomFormItem>

          </div>
          <div className="w-full items-center mt-2">
            <Button style={{ background: currentColor }} className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
